def page_events(payload, band, followed=()):
    from datetime import datetime, timezone
    from collections import Counter
    events=payload['events']
    if not events and payload.get('metadata_pending') is True and band:
        return {**payload,'pagination':{'total':0,'remaining_bands':[],'band':band,'facets':{'leagues':[],'states':{}}}}
    if not band:
        return payload
    if band=='counts':
        return {k:v for k,v in {**payload,'events':[], 'pagination':{'total':len(events),'band':'counts'}}.items() if k!='poll'}
    def key(e):
        try:
            parsed=datetime.fromisoformat(e['start'].replace('Z','+00:00'))
            if parsed.tzinfo is None:return 'unscheduled'
            return parsed.astimezone(timezone.utc).strftime('%Y%m%dT%H%MZ')
        except (KeyError,TypeError,ValueError):
            return 'unscheduled'
    bands=sorted({key(e) for e in events})
    if band!='first' and band not in bands:
        raise ValueError('Unknown kickoff band')
    favorites={(str(t.get('league')),str(t.get('id'))) for t in followed}
    def mine(e):
        return any((str(e.get('league')),str(t.get('espn_id'))) in favorites for t in e.get('teams',[]))
    if band=='first':
        if len(events)<=24:
            selected=events;remaining=[]
        else:
            first=bands[0] if bands else None
            selected=[e for e in events if e.get('state')=='live' or mine(e) or key(e)==first]
            included={(e['league'],str(e['id'])) for e in selected}
            remaining=[k for k in bands if any(key(e)==k and (e['league'],str(e['id'])) not in included for e in events)]
    else:
        selected=[e for e in events if key(e)==band];remaining=[]
    facets={'leagues':sorted({e['league'] for e in events}),'states':dict(Counter(e.get('state') for e in events))}
    return {**payload,'events':selected,'pagination':{'total':len(events),'remaining_bands':remaining,
            'band':band,'facets':facets}}

