def event_metadata_target(query):
    """Optional exact metadata selection; never a route or permission grant."""
    if 'projection' in query:
        if query['projection']!=['cards'] or any(key in query for key in ('event','league','band')):
            raise ValueError('Choose the complete schedule card projection')
        return None
    if 'event' not in query:return None
    if ('band' in query or len(query['event'])!=1 or len(query.get('league',[]))!=1
            or not re.fullmatch(r'[0-9]{1,12}',query['event'][0]) or query['league'][0] not in LEAGUES):
        raise ValueError('Choose one exact supported event and league')
    return query['event'][0],query['league'][0]

def card_metadata_event(event):
    """Only typed schedule facts; nested tracker and source objects stay out."""
    import math
    def plain(value,limit):
        return (isinstance(value,str) and 0<len(value)<=limit and not any(ord(c)<32 for c in value)
                and '://' not in value and not value.lstrip().startswith(('/','\\'))
                and not value.lower().startswith(('data:','file:','javascript:')))
    result={}
    for key,limit in (('id',12),('event_id',12),('league',64),('name',240),('start',48),('state',24),('status',160),('carryover_date',10)):
        value=event.get(key)
        if plain(value,limit) and (key not in ('id','event_id') or re.fullmatch(r'[0-9]{1,12}',value)):
            result[key]=value
    for key in ('stale','report_stale','postseason','conference_game'):
        if type(event.get(key)) is bool:result[key]=event[key]
    for key in ('game_revision','season_type'):
        if type(event.get(key)) is int and 0<=event[key]<2**63:result[key]=event[key]
    stamp=event.get('fetched_at')
    if type(stamp) in (int,float) and math.isfinite(stamp) and 0<=stamp<1e12:result['fetched_at']=stamp
    epoch=event.get('timeline_epoch')
    if isinstance(epoch,str) and re.fullmatch(r'[a-f0-9]{24}',epoch):result['timeline_epoch']=epoch
    teams=event.get('teams')
    if isinstance(teams,list) and len(teams)<=2:
        result['teams']=[]
        for team in teams:
            if not isinstance(team,dict):continue
            row={}
            for key,limit in (('name',160),('short',64),('abbreviation',12),('abbr',12),('record',40),('rank_display',8)):
                if plain(team.get(key),limit):row[key]=team[key]
            if team.get('side') in ('away','home'):row['side']=team['side']
            for key in ('id','espn_id','conference_id'):
                value=team.get(key)
                if isinstance(value,str) and re.fullmatch(r'[0-9]{1,12}',value):row[key]=value
            score=team.get('score')
            if isinstance(score,str) and re.fullmatch(r'[0-9]{1,3}',score) or type(score) is int and 0<=score<=999:row['score']=score
            if type(team.get('rank')) is int and 1<=team['rank']<=99:row['rank']=team['rank']
            result['teams'].append(row)
    networks=event.get('networks')
    if isinstance(networks,list) and len(networks)<=4:result['networks']=[v for v in networks if plain(v,80)]
    result['source_projection']='deferred'
    return result

def get_json(url, token=None):
    headers = {'Accept': 'application/json', 'User-Agent': 'curl/8.7.1'}
    if token:
        headers['X-Emby-Token'] = token
    with urllib.request.urlopen(urllib.request.Request(url, headers=headers), timeout=8) as response:
        body = response.read(8*1024*1024+1)
        if len(body) > 8*1024*1024:
            raise ValueError('response limit')
        return json.loads(body)

PROGRESSIVE_POOL = concurrent.futures.ThreadPoolExecutor(max_workers=4)

PROGRESSIVE_PENDING = set()

def metadata_refresh(key, action):
    with LOCK:
        if key in PROGRESSIVE_PENDING or len(PROGRESSIVE_PENDING) >= 32:
            return
        PROGRESSIVE_PENDING.add(key)
    def run():
        try:
            action()
        except Exception:
            pass  # The response keeps original age and an explicit pending state.
        finally:
            with LOCK:
                PROGRESSIVE_PENDING.discard(key)
    try:
        PROGRESSIVE_POOL.submit(run)
    except Exception:
        with LOCK:
            PROGRESSIVE_PENDING.discard(key)

def progressive_schedule(day, carryover=False):
    date.fromisoformat(day)
    with LOCK:
        old = CACHE.get(day)
    age = time.time()-old['fetched_at'] if old else float('inf')
    lifetime = (1800 if date.fromisoformat(day) < datetime.now(ZONE).date()
                and not carryover and old and not any(e.get('state')=='live' for e in old['events']) else 120)
    if old and age < lifetime:
        return old
    metadata_refresh(('schedule',day),lambda:schedule(day,carryover))
    if old and age <= max(lifetime,600):
        return {**old,'stale':True,'metadata_pending':True,
                'events':[{**e,'stale':True,'fetched_at':e.get('fetched_at',old['fetched_at'])} for e in old['events']],
                'warnings':list(old.get('warnings',[]))+['Schedule is updating; showing its original observation'],
                'retry_after_seconds':2}
    return {'events':[],'warnings':['Schedule is updating; retry shortly'],'fetched_at':None,
            'schedule_source':'ESPN schedules','leagues':list(LEAGUES),'date':day,
            'stale_leagues':[],'stale':True,'metadata_pending':True,'retry_after_seconds':2}

def board_reported_event(base,day):
    """Read an already owned report without refresh, normalization or publication.

    Card discovery must not renew tracker ownership or wait for a different
    game's network acquisition. Direct tracker/Game Center endpoints retain
    their existing acquisition path. Full-day context still receives already
    owned lifecycle facts before collision checks and kickoff-band selection.
    """
    league=base.get('league');event=base.get('id') or base.get('event_id')
    if league not in ('MLB','NFL','College football'):return base
    try:
        import tracker
        cache=tracker.CACHE
        with cache.lock:
            entry=cache.entries.get((league,str(event),day))
            if entry is None or entry.get('data') is None:return base
            owned=entry['data']
            if (owned.get('league')!=league or str(owned.get('event_id'))!=str(event)
                    or datetime.fromisoformat(owned['start'].replace('Z','+00:00'))
                    !=datetime.fromisoformat(base['start'].replace('Z','+00:00'))):return base
            owned_start=owned['start']
            age=cache.clock()-entry['updated']
        snapshot=cache.game_store.peek(league,str(event))
        if (not isinstance(snapshot,dict) or snapshot.get('league')!=league
                or str(snapshot.get('game_id'))!=str(event)):return base
        # The canonical entry is published before GameStore. A same-ID store
        # may still represent an earlier kickoff; bind the actual store epoch
        # without normalization, acquisition or publication.
        source='ESPN';game_pk=None;epoch_start=owned_start;lane_delayed=False
        if league=='MLB':
            reported=cache.reported_mlb.peek(owned)
            lane=reported.get('reported_mlb') if isinstance(reported,dict) else None
            if (not isinstance(lane,dict) or lane.get('source')!='MLB'
                    or str(lane.get('event_id'))!=str(event)
                    or type(lane.get('game_pk')) is not int or type(lane.get('stale')) is not bool):return base
            source='MLB';game_pk=lane['game_pk'];epoch_start=lane.get('binding',{}).get('start_at') or owned_start
            if datetime.fromisoformat(epoch_start.replace('Z','+00:00'))!=datetime.fromisoformat(owned_start.replace('Z','+00:00')):return base
            lane_delayed=lane['stale']
        expected_epoch=tracker._game_snapshot.digest([source,str(event),game_pk,epoch_start,'provider-event-coordinate-v1'])[:24]
        if snapshot.get('source')!=source or snapshot.get('timeline_epoch')!=expected_epoch:return base
        observed=snapshot.get('health_observed_at')
        # MLB's independent receipt lane has a shorter freshness contract than
        # the canonical cache. A list read must not extend that observed age.
        fresh_for=cache.reported_mlb.STALE if league=='MLB' else cache.SERVE
        if (lane_delayed or age<0 or age>=cache.SERVE or type(observed) not in (int,float)
                or not 0<=cache.wall()-observed<fresh_for):
            snapshot={**snapshot,'source_health':'delayed'}
        return _report_health_split(base,tracker._game_snapshot.overlay_latest(base,snapshot))
    except (AttributeError,KeyError,TypeError,ValueError):
        return base

_broadcast_resolution_source = b'"""Game-specific MLB broadcast metadata, never picture/transport/rights proof.\n\nPure adapter: exact two-sided team/start binding, bounded TV rows only. A series\nor family-wide ESPN network list cannot defeat a complete per-game league list.\n"""\nfrom datetime import datetime, timezone\n\nCALLSIGNS = {\n    \'fox\': \'FOX\', \'fs1\': \'FS1\', \'fox sports 1\': \'FS1\',\n    \'fs2\': \'FS2\', \'fox sports 2\': \'FS2\', \'fox dep.\': \'FOX Deportes\',\n    \'fox deportes\': \'FOX Deportes\', \'espn\': \'ESPN\', \'espn2\': \'ESPN2\',\n    \'espnu\': \'ESPNU\', \'espnews\': \'ESPNews\', \'abc\': \'ABC\', \'nbc\': \'NBC\',\n    \'cbs\': \'CBS\', \'tbs\': \'TBS\', \'tnt\': \'TNT\', \'trutv\': \'truTV\',\n    \'mlb network\': \'MLB Network\', \'mlbn\': \'MLB Network\',\n}\n\n\ndef stamp(value):\n    if not isinstance(value, str) or len(value) > 48:\n        return None\n    try:\n        result = datetime.fromisoformat(value.replace(\'Z\', \'+00:00\'))\n        return result.astimezone(timezone.utc) if result.utcoffset() is not None else None\n    except (ValueError, TypeError, OverflowError):\n        return None\n\n\ndef resolve(event, payload, normalize_name):\n    if (not isinstance(event, dict) or event.get(\'league\') != \'MLB\'\n            or not isinstance(payload, dict) or not isinstance(payload.get(\'dates\'), list)\n            or len(payload[\'dates\']) > 3):\n        return None\n    start = stamp(event.get(\'start\'))\n    teams = event.get(\'teams\')\n    if not start or not isinstance(teams, list) or len(teams) != 2:\n        return None\n    def name(value):\n        return normalize_name(value) if isinstance(value, str) else \'\'\n    sides = {t.get(\'side\'): name(t.get(\'name\')) for t in teams if isinstance(t, dict)}\n    if set(sides) != {\'away\', \'home\'} or not all(sides.values()) or sides[\'away\'] == sides[\'home\']:\n        return None\n    games = []\n    for day in payload[\'dates\']:\n        if not isinstance(day, dict) or not isinstance(day.get(\'games\'), list) or len(day[\'games\']) > 64:\n            return None\n        for game in day[\'games\']:\n            if not isinstance(game, dict):\n                return None\n            when = stamp(game.get(\'gameDate\'))\n            raw_teams = game.get(\'teams\')\n            if not isinstance(raw_teams, dict):\n                continue\n            names = {}\n            for side in (\'away\', \'home\'):\n                side_row = raw_teams.get(side)\n                team = side_row.get(\'team\') if isinstance(side_row, dict) else None\n                names[side] = name(team.get(\'name\')) if isinstance(team, dict) else \'\'\n            if when and abs((when - start).total_seconds()) <= 60 and names == sides:\n                games.append(game)\n    if len(games) != 1:\n        return None\n    game = games[0]\n    if type(game.get(\'gamePk\')) is not int or game[\'gamePk\'] <= 0:\n        return None\n    rows = game.get(\'broadcasts\')\n    if not isinstance(rows, list) or not 0 < len(rows) <= 64:\n        return None\n    if any(not isinstance(row, dict) or not isinstance(row.get(\'type\'), str)\n           or (row[\'type\'] == \'TV\' and type(row.get(\'isNational\')) is not bool) for row in rows):\n        return None\n    national = [row for row in rows if isinstance(row, dict) and row.get(\'type\') == \'TV\'\n                and row.get(\'isNational\') is True and row.get(\'postGameShow\') is not True\n                and row.get(\'preGameShow\') is not True]\n    if not national:\n        return None\n    networks = []\n    for row in sorted(national, key=lambda row: row.get(\'language\') != \'en\'):\n        call = row.get(\'callSign\')\n        channel = CALLSIGNS.get(call.casefold().strip()) if isinstance(call, str) else None\n        # Partial recognition is not a complete conflicting-network authority.\n        if not channel or row.get(\'language\') not in (\'en\', \'es\', \'fr\'):\n            return None\n        if channel not in networks:\n            networks.append(channel)\n        # FOX One is a distinct advertised platform, never an alias for FS1/FOX.\n        name = row.get(\'name\')\n        if isinstance(name, str) and any(part.strip().casefold() == \'fox one\' for part in name.split(\'/\')):\n            if \'FOX One\' not in networks:\n                networks.append(\'FOX One\')\n    return {\'basis\': \'league_game_specific_national_tv\', \'event_id\': event.get(\'id\'), \'game_id\': game[\'gamePk\'],\n            \'start\': event[\'start\'], \'networks\': networks,\n            \'picture_verdict\': \'unknown\'}\n\n\ndef apply(event, payload, normalize_name):\n    proof = resolve(event, payload, normalize_name)\n    if proof is None:\n        return dict(event)\n    previous = event.get(\'schedule_networks\', event.get(\'networks\', []))\n    previous = [value for value in previous if isinstance(value, str) and len(value) <= 80] if isinstance(previous, list) else []\n    return {**event, \'networks\': list(proof[\'networks\']), \'schedule_networks\': previous,\n            \'discovery_networks\': list(dict.fromkeys(previous + proof[\'networks\'])),\n            \'broadcast_resolution\': proof}\n'

if __import__('hashlib').sha256(_broadcast_resolution_source).hexdigest() != '116c3e285bfd7a2a0773494da18c67aa4d321b82cadc4d9c3148193ba3b32c0d':
    raise RuntimeError('BroadcastResolutionSourceDrift')

_broadcast_resolution = __import__('types').ModuleType('broadcast_resolution')

exec(compile(_broadcast_resolution_source, '<broadcast_resolution>', 'exec'), _broadcast_resolution.__dict__)

MLB_BROADCAST_CACHE, MLB_BROADCAST_PENDING = {}, {}

MLB_BROADCAST_POOL = concurrent.futures.ThreadPoolExecutor(max_workers=1)

def resolve_mlb_broadcast(event):
    if event.get('league') != 'MLB':
        return dict(event)
    # A prior enriched caller cannot renew derived schedule authority after
    # expiry/failure. Only the current cache/fetch can supply it again.
    event = dict(event)
    if 'broadcast_resolution' in event:
        event['networks'] = event.get('schedule_networks', [])
        for field in ('broadcast_resolution', 'schedule_networks', 'discovery_networks'):
            event.pop(field, None)
    try:
        day = datetime.fromisoformat(event['start'].replace('Z', '+00:00')).astimezone(ZONE).date().isoformat()
        now = time.time()
        with LOCK:
            cached = MLB_BROADCAST_CACHE.get(day)
            if cached and 0 <= now - cached['fetched_at'] < 120:
                if cached['data'] is not None:
                    return _broadcast_resolution.apply(event, cached['data'], team_name)
                if now - cached['fetched_at'] < 15:
                    return dict(event)
            if day in MLB_BROADCAST_PENDING or len(MLB_BROADCAST_PENDING) >= 2:
                return dict(event)
            MLB_BROADCAST_PENDING[day] = True
        def fetch():
            data = None
            try:
                data = get_json('https://statsapi.mlb.com/api/v1/schedule?' + urlencode(
                    {'sportId': 1, 'date': day, 'hydrate': 'broadcasts(all)'}))
            except (OSError, ValueError, KeyError, TypeError, AttributeError, OverflowError):
                pass
            finally:
                with LOCK:
                    MLB_BROADCAST_CACHE[day] = {'data': data, 'fetched_at': time.time()}
                    while len(MLB_BROADCAST_CACHE) > 8:
                        MLB_BROADCAST_CACHE.pop(next(iter(MLB_BROADCAST_CACHE)))
                    MLB_BROADCAST_PENDING.pop(day, None)
        try:
            MLB_BROADCAST_POOL.submit(fetch)
        except RuntimeError:
            with LOCK:
                MLB_BROADCAST_PENDING.pop(day, None)
        # First paint never waits on the additional official metadata request.
        # The next refresh uses it after the bounded background request finishes.
        return dict(event)
    except (OSError, ValueError, KeyError, TypeError, AttributeError, OverflowError):
        return dict(event)

def team_name(value):
    return (value or '').replace('Athletics Athletics', 'Athletics').strip()

def poll_rank(value):
    """ESPN marks unranked teams as 99; only 1-25 is a real poll position."""
    try:
        rank = int(value)
    except (TypeError, ValueError):
        return None
    return rank if 1 <= rank <= 25 else None

RANKINGS_URL = 'https://site.api.espn.com/apis/site/v2/sports/football/college-football/rankings'

FBS_POLLS = ('AP Top 25', 'AFCA Coaches Poll', 'College Football Playoff Rankings')

FBS_GROUP = '80'

RANKINGS_TTL = 6*3600

RANKINGS = {}

def parse_rankings(payload, fetched_at=None):
    polls = []
    for poll in payload.get('rankings', []):
        if poll.get('name') not in FBS_POLLS:
            continue
        teams = []
        for entry in poll.get('ranks', []):
            team = entry.get('team', {})
            rank = poll_rank(entry.get('current'))
            if rank is None or not team.get('id'):
                continue
            # Belt and braces: a poll we call FBS must only carry FBS (group 80) teams.
            if str(team.get('groups', {}).get('parent', {}).get('id', FBS_GROUP)) != FBS_GROUP:
                continue
            # In this payload `location` is the school ("Texas"), `name` the mascot ("Longhorns") and
            # `nickname` the short name; the scoreboard's displayName is "<location> <name>".
            location, mascot = team_name(team.get('location')), team_name(team.get('name'))
            teams.append({'rank': rank, 'previous': poll_rank(entry.get('previous')), 'trend': entry.get('trend') or '-',
                          'espn_id': str(team['id']), 'name': (location+' '+mascot).strip(), 'location': location,
                          'short': team_name(team.get('nickname')) or location, 'abbreviation': team.get('abbreviation') or '',
                          'record': entry.get('recordSummary') or '',
                          'logo': team.get('logo') if str(team.get('logo', '')).startswith('https://a.espncdn.com/') else None})
        polls.append({'name': poll['name'], 'short': poll.get('shortName') or poll['name'],
                      'week': poll.get('occurrence', {}).get('number'), 'date': poll.get('date'),
                      'headline': poll.get('headline') or '', 'teams': sorted(teams, key=lambda t: t['rank'])})
    if not polls:
        raise ValueError('No FBS poll in rankings payload')
    return {'polls': polls, 'fetched_at': fetched_at or time.time(), 'stale': False}

def rankings(progressive=False):
    """FBS Top 25 polls, cached; a failed refresh serves the last good copy flagged stale."""
    with LOCK:
        cached = RANKINGS.get('data')
        if cached and time.time()-cached['fetched_at'] < RANKINGS_TTL:
            return cached
    if progressive:
        metadata_refresh(('rankings',),lambda:rankings())
        return {**cached,'stale':True} if cached else {'polls':[],'stale':True,'fetched_at':None}
    try:
        fresh = parse_rankings(get_json(RANKINGS_URL))
    except Exception:
        if not cached:
            raise
        return {**cached, 'stale': True}
    with LOCK:
        RANKINGS['data'] = fresh
    return fresh

def annotate_ranks(events, polls):
    """Attach the AP rank (first FBS poll) to college football teams by ESPN id, else exact name."""
    poll = next(iter(polls or []), None)
    if not poll:
        return events
    by_id = {t['espn_id']: t['rank'] for t in poll['teams']}
    # Exact display name only: "Texas Longhorns" must never rank "Texas Tech Red Raiders".
    by_name = {t['name'].lower(): t['rank'] for t in poll['teams']}
    result = []
    for event in events:
        if event.get('league') != 'College football':
            result.append(event)
            continue
        teams = []
        for team in event.get('teams', []):
            rank = by_id.get(team.get('espn_id') or '') or by_name.get(team_name(team.get('name')).lower())
            teams.append({**team, 'rank': rank})
        result.append({**event, 'teams': teams})
    return result

WATCH_EARLY, WATCH_LATE = timedelta(minutes=15), timedelta(hours=5)

def watchable(event, now=None):
    """Sept 25: a game can be watched when it is live, or from 15 minutes before its scheduled
    start while ESPN still says 'scheduled' (pregame coverage is already on the feeds)."""
    if event.get('state') == 'live':
        return True
    if event.get('state') != 'scheduled':
        return False
    try:
        start = datetime.fromisoformat(str(event.get('start')).replace('Z', '+00:00'))
    except ValueError:
        return False
    now = now or datetime.now(timezone.utc)
    return start - WATCH_EARLY <= now <= start + WATCH_LATE

FINAL_CACHE = {}

DECISION_ROLES = {'winningPitcher': 'Winning pitcher', 'losingPitcher': 'Losing pitcher', 'savingPitcher': 'Save',
                  'winningGoalie': 'Winning goalie', 'losingGoalie': 'Losing goalie', 'firstStar': 'First star',
                  'secondStar': 'Second star', 'thirdStar': 'Third star'}

FINAL_TTL = 6 * 3600

FINAL_MAX = 400

def final_summary(league, event_id):
    """Cached finished-game summary: revalidated after FINAL_TTL, bounded, previous copy on error."""
    key = (league, str(event_id))
    hit = FINAL_CACHE.get(key)
    if hit and time.time() - hit[0] < FINAL_TTL:
        return hit[1]
    try:
        result = _fetch_final_summary(league, event_id)
    except Exception:
        if hit:
            return hit[1]
        raise
    if result is not None:
        FINAL_CACHE.pop(key, None)
        FINAL_CACHE[key] = (time.time(), result)
        while len(FINAL_CACHE) > FINAL_MAX:
            FINAL_CACHE.pop(next(iter(FINAL_CACHE)))
    return result

def _fetch_final_summary(league, event_id):
    """Sept 25: what a finished game's Summary shows -- scoring plays with the running score and
    the decisions (pitchers, goalies, stars). ESPN summary endpoint."""
    if league not in LEAGUES or league in ('NBA', 'WNBA', 'UFC / MMA') or not re.fullmatch(r'[0-9]{1,12}', str(event_id)):
        return None
    data = get_json('https://site.api.espn.com/apis/site/v2/sports/' + LEAGUES[league] + '/summary?event=' + str(event_id))
    comp = next(iter(data.get('header', {}).get('competitions', [])), {})
    names = {str(c.get('id')): c.get('team', {}).get('displayName') for c in comp.get('competitors', [])}
    def clean(value, limit):
        value = ' '.join(str(value or '').split())
        return value[:limit] if value and not re.search(r'https?://', value) else ''
    rows = data.get('scoringPlays') or [p for p in data.get('plays') or [] if p.get('scoringPlay')]
    scoring = []
    for p in rows[:40]:
        period = p.get('period') or {}
        team = p.get('team') or {}
        label = clean(period.get('displayValue'), 20) or (('Q' if league in ('NFL', 'College football') else 'P') + str(period.get('number'))
                                                        if period.get('number') else '')
        scoring.append({'period': label, 'clock': clean((p.get('clock') or {}).get('displayValue'), 10) or None,
                        'team': clean(team.get('displayName') or names.get(str(team.get('id'))), 60) or None,
                        'text': clean(p.get('text'), 160), 'away': p.get('awayScore'), 'home': p.get('homeScore')})
    decisions = [{'role': DECISION_ROLES[f['name']], 'name': clean(f.get('athlete', {}).get('displayName'), 60)}
                 for f in comp.get('status', {}).get('featuredAthletes', []) if f.get('name') in DECISION_ROLES
                 and f.get('athlete', {}).get('displayName')]
    return {'scoring': [s for s in scoring if s['text']], 'decisions': decisions, 'truncated': len(rows) > 40}

def normalize(raw, league):
    status = raw.get('status', {}).get('type', {})
    state = 'live' if status.get('state') == 'in' else 'final' if status.get('completed') else 'scheduled'
    label = status.get('shortDetail') or status.get('description') or state.title()
    if state == 'scheduled' and status.get('name') != 'STATUS_DELAYED':
        label = 'Scheduled'
    if status.get('name') in ('STATUS_POSTPONED', 'STATUS_CANCELED', 'STATUS_CANCELLED'):
        state = 'unavailable'
        label = 'Postponed' if status.get('name') == 'STATUS_POSTPONED' else 'Canceled'  # Sept 28: was overwritten to 'Scheduled'
    competitions = raw.get('competitions', [])
    if league == 'UFC / MMA':
        # One watchable card per event, not one duplicate feed per bout. ESPN orders
        # bouts from prelims to the main event; athlete fields differ from team sports.
        main = competitions[-1] if competitions else {}
        fighters = main.get('competitors', [])
        teams = [{'name': v.get('athlete', {}).get('displayName') or v.get('athlete', {}).get('fullName') or '',
                  'score': None, 'side': 'away' if i == 0 else 'home',
                  'espn_id': str(v.get('id') or '') or None, 'rank': None}
                 for i, v in enumerate(fighters)]
        active = next((c for c in competitions if c.get('status', {}).get('type', {}).get('state') == 'in'), None)
        detail = active.get('status', {}).get('type', {}).get('shortDetail') if active else None
        label = (raw.get('shortName') or 'UFC') + ' Â· ' + (detail or label)
        out = {'id': str(raw['id']), 'league': league, 'name': raw.get('name') or 'UFC event',
               'start': raw['date'], 'state': state, 'status': label, 'teams': teams}
        return out | {'watchable': watchable(out)}
    competitors = next(iter(competitions), {}).get('competitors', [])
    teams = [{'name': team_name(v.get('team', {}).get('displayName', '')), 'score': v.get('score'),
              'side': v.get('homeAway'), 'espn_id': str(v.get('team', {}).get('id') or '') or None,
              'rank': poll_rank(v.get('curatedRank', {}).get('current'))} for v in competitors]
    # Sept 29 polish (additive): record, short name, abbreviation and conference for board cards and the game header.
    for team, v in zip(teams, competitors):
        t = v.get('team') or {}
        logo = t.get('logo') or next((x.get('href') for x in (t.get('logos') or []) if isinstance(x, dict) and x.get('href')), '')
        try:
            image = urlsplit(logo) if isinstance(logo, str) else None
            if image and image.scheme == 'https' and image.hostname and not image.username and not image.password and not image.fragment and len(logo) <= 2048:
                team['logo'] = logo
        except ValueError:
            pass
        record = next((r.get('summary') for r in (v.get('records') or []) if isinstance(r, dict) and r.get('type') in ('total', 'overall', None)), None)
        extra = {'record': record if isinstance(record, str) and re.fullmatch(r'[0-9]{1,3}(-[0-9]{1,3}){1,2}', record) else None,
                 'short': (t.get('shortDisplayName') or '')[:40] or None, 'abbr': (t.get('abbreviation') or '')[:8] or None,
                 'conference_id': str(t.get('conferenceId') or '') or None}
        team.update({k: val for k, val in extra.items() if val})
    competition = next(iter(competitions), {})
    networks = []
    for b in competition.get('broadcasts') or []:
        for name in (b.get('names') or []) if isinstance(b, dict) else []:
            if isinstance(name, str) and name and name not in networks and len(networks) < 4:
                networks.append(name[:24])
    venue = (competition.get('venue') or {}).get('fullName')
    out = {'id': str(raw['id']), 'league': league, 'name': raw.get('name', 'Game').replace('Athletics Athletics', 'Athletics'),
           'start': raw['date'], 'state': state, 'status': label, 'teams': teams}
    if mlb_postseason(raw, league): out.update(postseason=True, season_type=3)
    if networks: out['networks'] = networks
    if isinstance(venue, str) and venue: out['venue'] = venue[:80]
    if competition.get('conferenceCompetition') is True: out['conference_game'] = True
    return out | {'watchable': watchable(out)}

def core_event(raw, league, now=None):
    """Normalize ESPN's lower-level event endpoint.

    The scoreboard endpoint is convenient, but it is occasionally rejected at
    the edge while the core event API remains available.  Event names and IDs
    are kept intact so exact ESPN-ID matching keeps working.
    """
    now = now or datetime.now(timezone.utc)
    start = datetime.fromisoformat(raw['date'].replace('Z', '+00:00'))
    state, label = ('scheduled', 'Scheduled')
    status = raw.get('_resolved_status', {}).get('type', {})
    if status:
        state = 'live' if status.get('state') == 'in' else 'final' if status.get('completed') else 'scheduled'
        label = status.get('shortDetail') or status.get('description') or state.title()
        if status.get('name') in ('STATUS_POSTPONED', 'STATUS_CANCELED', 'STATUS_CANCELLED'):
            state = 'unavailable'
    elif start < now-timedelta(hours=8):
        state, label = ('unresolved', 'Status unavailable')
    name = raw.get('name') or raw.get('shortName') or 'Game'
    separator = ' at ' if ' at ' in name else ' vs. ' if ' vs. ' in name else ' vs ' if ' vs ' in name else None
    teams = []
    if separator:
        matchup = name.split(':', 1)[-1].strip() if league == 'UFC / MMA' else name
        left, right = matchup.split(separator, 1)
        scores = raw.get('_resolved_scores', {})
        teams = [{'name': team_name(left), 'score': scores.get('away'), 'side': 'away'},
                 {'name': team_name(right), 'score': scores.get('home'), 'side': 'home'}]
    out = {'id': str(raw['id']), 'league': league, 'name': name.replace('Athletics Athletics', 'Athletics'),
           'start': raw['date'], 'state': state, 'status': label, 'teams': teams}
    if mlb_postseason(raw, league): out.update(postseason=True, season_type=3)
    return out | {'watchable': watchable(out, now)}

def core_schedule(league, chosen):
    """Read one date from ESPN Core with bounded parallel detail requests."""
    sport, slug = LEAGUES[league].split('/', 1)
    url = ('https://sports.core.api.espn.com/v2/sports/'+sport+'/leagues/'+slug+
           '/events?'+urlencode({'dates': chosen.strftime('%Y%m%d'), 'limit': 500}))
    index = get_json(url)
    items = index.get('items')
    if not isinstance(items, list) or int(index.get('count', len(items))) > 500 or index.get('pageCount', 1) not in (0, 1):
        raise ValueError('core pagination limit')
    now = datetime.now(timezone.utc)

    def load(item):
        ref = str(item.get('$ref') or '')
        if not ref.startswith(('http://sports.core.api.espn.com/', 'https://sports.core.api.espn.com/')):
            raise ValueError('unexpected core reference')
        raw = get_json('https://'+ref.split('://', 1)[1])
        start = datetime.fromisoformat(raw['date'].replace('Z', '+00:00'))
        # Resolve status and scores for the active/recent window. This keeps
        # yesterday's final scores available when ESPN's richer scoreboard is
        # temporarily unavailable, without multiplying requests for future games.
        if now-timedelta(hours=36) <= start <= now+timedelta(hours=2):
            competitions = raw.get('competitions', [])
            # A finished prelim is not a finished UFC card. Core fallback uses
            # the main event's status; the richer scoreboard owns whole-card live status.
            competition = (competitions[-1] if competitions else {}) if league == 'UFC / MMA' else next(iter(competitions), {})
            status_ref = competition.get('status', {}).get('$ref', '')
            if status_ref.startswith(('http://sports.core.api.espn.com/', 'https://sports.core.api.espn.com/')):
                try:
                    raw['_resolved_status'] = get_json('https://'+status_ref.split('://', 1)[1])
                except (OSError, ValueError, KeyError, TypeError):
                    pass
            scores = {}
            for competitor in competition.get('competitors', []):
                side = competitor.get('homeAway')
                score_ref = competitor.get('score', {}).get('$ref', '')
                if side not in ('home', 'away') or not score_ref.startswith(
                        ('http://sports.core.api.espn.com/', 'https://sports.core.api.espn.com/')):
                    continue
                try:
                    score = get_json('https://'+score_ref.split('://', 1)[1])
                    value = score.get('displayValue')
                    if value is None and score.get('value') is not None:
                        value = f"{float(score['value']):g}"
                    if value is not None:
                        scores[side] = str(value)
                except (OSError, ValueError, KeyError, TypeError):
                    pass
            if scores:
                raw['_resolved_scores'] = scores
        return core_event(raw, league, now)

    with concurrent.futures.ThreadPoolExecutor(max_workers=12) as pool:
        return list(pool.map(load, items))

def schedule(day, carryover=False, progressive=False):
    """Coalesce one date without holding the cache lock over network work."""
    if progressive:
        return progressive_schedule(day,carryover)
    date.fromisoformat(day)
    with LOCK:
        old = CACHE.get(day)
        if old and time.time()-old['fetched_at'] < (1800 if date.fromisoformat(day) < datetime.now(ZONE).date() and not carryover and not any(event.get('state') == 'live' for event in old['events']) else 120):
            return old
        pending = REFRESHING.get(day)
        owner = pending is None
        if owner:
            pending = REFRESHING[day] = threading.Event()
    if not owner:
        if old:
            return {**old, 'stale': True}
        if not pending.wait(50):
            raise TimeoutError('Schedule refresh is still running')
        with LOCK:
            ready = CACHE.get(day)
        if ready is None:
            raise ValueError('Schedule refresh failed; retry')
        return ready
    try:
        return refresh_schedule(day, old)
    finally:
        with LOCK:
            REFRESHING.pop(day, None)
            pending.set()

def schedule_board(day, today):
    """Today includes yesterday's still-reported-live games, with original ages."""
    current = schedule(day,progressive=True)
    events = supplement(current['events'], day)
    if day != today.isoformat():
        return {**current, 'events': events}
    prior_day = (today - timedelta(days=1)).isoformat()
    try:
        prior = schedule(prior_day, carryover=True, progressive=True)
    except (OSError, ValueError, KeyError, TypeError, TimeoutError):
        return {**current, 'events': events, 'warnings': list(current['warnings']) +
                ['Previous-day live status unavailable; current board retained']}
    # An endpoint may list the same game on both dates. Retain one complete
    # reported row, preferring the later original fetch; never merge game facts.
    def fetched(board, event):
        value = event.get('fetched_at', 0 if event.get('stale') is True else board.get('fetched_at', 0))
        return value if isinstance(value, (int, float)) and not isinstance(value, bool) and 0 < value < 1e12 else 0
    merged, stamps = {}, {}
    for event in events:
        key = str(event['id'])
        stamp = fetched(current, event)
        if key not in merged or stamp > stamps[key]:
            merged[key], stamps[key] = event, stamp
    carried = []
    for event in supplement(prior['events'], prior_day):
        key = str(event['id'])
        stamp = fetched(prior, event)
        if event.get('state') != 'live':
            if key in merged and stamp > stamps[key]:
                try:
                    old_start = datetime.fromisoformat(merged[key]['start'].replace('Z', '+00:00'))
                    new_start = datetime.fromisoformat(event['start'].replace('Z', '+00:00'))
                    same_prior_start = old_start.tzinfo is not None and new_start.tzinfo is not None and old_start == new_start and old_start.astimezone(ZONE).date().isoformat() == prior_day
                except (KeyError, TypeError, ValueError):
                    same_prior_start = False
                if same_prior_start and event.get('state') in ('final', 'unavailable', 'scheduled'):
                    del merged[key], stamps[key]
                elif same_prior_start and merged[key].get('state') == 'live':
                    merged[key] = {**merged[key], 'stale': True,
                                   'fetched_at': merged[key].get('fetched_at', current.get('fetched_at'))}
            continue
        if key in merged and stamp <= stamps[key]:
            continue
        row = {**event, 'carryover_date': prior_day}
        if 'fetched_at' not in row:
            row['fetched_at'] = None if event.get('stale') is True else prior.get('fetched_at')
        if prior.get('stale') is True or event.get('league') in prior.get('stale_leagues', []):
            row['stale'] = True
        merged[key], stamps[key] = row, stamp
        carried.append(row)
    warnings = list(current['warnings'])
    if prior.get('metadata_pending'):
        warnings.append('Previous-day status is updating; current board retained')
    stale_leagues = list(current.get('stale_leagues', []))
    if carried:
        warnings.extend(w for w in prior.get('warnings', []) if w not in warnings)
        for event in carried:
            if event.get('stale') is True and event.get('league') not in stale_leagues:
                stale_leagues.append(event.get('league'))
    # Top-level fetched_at remains today's fetch. Carryover rows expose their
    # own original fetch; no request, pagination or cache hit renews that age.
    return {**current, 'events': list(merged.values()), 'warnings': warnings,
            'stale_leagues': stale_leagues, 'metadata_pending':bool(current.get('metadata_pending') or prior.get('metadata_pending')),
            **({'retry_after_seconds':2} if current.get('metadata_pending') or prior.get('metadata_pending') else {})}

def refresh_schedule(day, old=None):
    # Upstream requests run outside LOCK; cached dates remain immediately usable.
    chosen = date.fromisoformat(day)
    def fetch(league):
        events, failures = {}, []
        groups = ('90', '35') if league == 'College football' else (None,)
        scoreboard_ok = False
        group_failed = False
        for group in groups:
            try:
                # ESPN's site scoreboard accepts one calendar day. The old
                # three-day range is rejected with HTTP 400 and silently
                # forced every league onto the scoreless Core fallback.
                params = {'dates': chosen.strftime('%Y%m%d')}
                if group:
                    params['groups'] = group
                payload = get_json('https://site.api.espn.com/apis/site/v2/sports/'+LEAGUES[league]+'/scoreboard?'+urlencode(params))
                if not isinstance(payload.get('events'), list):
                    raise ValueError('missing events')
                scoreboard_ok = True
                if league == 'College football' and len(payload['events']) == 25:
                    failures.append(league+' coverage may be truncated')
                for raw in payload['events']:
                    event = normalize(raw, league)
                    local_day = datetime.fromisoformat(event['start'].replace('Z', '+00:00')).astimezone(ZONE).date()
                    if local_day == chosen or (event['state'] == 'live' and chosen == datetime.now(ZONE).date()):
                        events[event['id']] = event
            except (OSError, ValueError, KeyError, TypeError):
                group_failed = True
        source = 'ESPN scoreboard'
        failed = False
        if not scoreboard_ok:
            try:
                for event in core_schedule(league, chosen):
                    events[event['id']] = event
                source = 'ESPN core fallback'
            except (OSError, ValueError, KeyError, TypeError):
                failures.append(league+' unavailable')
                failed = True
        elif group_failed:
            failures.append(league+' partly unavailable')
            failed = True
        return list(events.values()), failures, source, failed
    # Review v2 D03: last-good is per league. A failed league (or college group) keeps its previous
    # events, marked stale, instead of disappearing because another league refreshed successfully.
    previous = {}
    for event in (old or {}).get('events', []):
        previous.setdefault(event.get('league'), []).append(event)
    events, failures, sources, stale_leagues = [], [], [], []
    with concurrent.futures.ThreadPoolExecutor(max_workers=4) as pool:
        for league, (items, errors, source, failed) in zip(list(LEAGUES), pool.map(fetch, LEAGUES)):
            if failed and previous.get(league):
                have = {e['id'] for e in items}
                kept = [{**e, 'stale': True, 'fetched_at': e.get('fetched_at', None if e.get('stale') is True else (old or {}).get('fetched_at'))} for e in previous[league] if e['id'] not in have]
                if kept:
                    items = items + kept
                    stale_leagues.append(league)
            events.extend(items)
            failures.extend(errors)
            sources.append(source)
    if stale_leagues:
        failures.append('Showing the previous schedule for ' + ', '.join(stale_leagues) + '; status may be outdated')
    result = {'events': events, 'warnings': failures, 'fetched_at': time.time(),
              'schedule_source': 'ESPN resilient schedule endpoints' if 'ESPN core fallback' in sources else 'ESPN schedules',
              'leagues': list(LEAGUES), 'date': day, 'stale_leagues': stale_leagues}
    if failures and not events and old:
        result = {**old, 'warnings': failures+['Showing the previous schedule; status may be outdated']}
    with LOCK:
        CACHE[day] = result
        for key in list(CACHE):
            if key < (datetime.now(ZONE).date()-timedelta(days=8)).isoformat():
                del CACHE[key]
    return result

def live_scoreboard(league, day):
    """One refresh per league/date, at most every 15 s; stale state is explicit."""
    key = (league, day)
    with LOCK:
        old = LIVE_BOARDS.get(key)
        if old and time.time()-old['fetched_at'] < 15:
            return old
        pending = LIVE_REFRESHING.get(key)
        owner = pending is None
        if owner:
            pending = LIVE_REFRESHING[key] = threading.Event()
    if not owner:
        if old:
            return {**old, 'stale': True}
        if not pending.wait(10):
            raise TimeoutError('Live state refresh pending')
        with LOCK:
            if key not in LIVE_BOARDS:
                raise ValueError('Live state unavailable')
            return LIVE_BOARDS[key]
    try:
        params = {'dates': date.fromisoformat(day).strftime('%Y%m%d'), 'limit': 500}
        if league == 'College football':
            params['groups'] = FBS_GROUP
        data = get_json('https://site.api.espn.com/apis/site/v2/sports/'+LEAGUES[league]+'/scoreboard?'+urlencode(params))
        if not isinstance(data.get('events'), list):
            raise ValueError('Missing live events')
        result = {'events': data['events'], 'fetched_at': time.time(), 'stale': False}
        with LOCK:
            LIVE_BOARDS[key] = result
            while len(LIVE_BOARDS) > 32:
                del LIVE_BOARDS[next(iter(LIVE_BOARDS))]
        return result
    except Exception:
        if old:
            return {**old, 'stale': True}
        raise
    finally:
        with LOCK:
            LIVE_REFRESHING.pop(key, None)
            pending.set()

def game_state(raw, league, fetched_at, stale=False):
    """Only render graphics supported by the current provider fields, never guesses."""
    event = resolve_mlb_broadcast(normalize(raw, league))
    comp = next(iter(raw.get('competitions', [])), {})
    situation = comp.get('situation') or {}
    result = {**event, 'fetched_at': fetched_at, 'stale': stale,
              'clock': raw.get('status', {}).get('displayClock'),
              'period': raw.get('status', {}).get('period'), 'graphics': None,
              'source': 'ESPN scoreboard'}
    result['venue'] = comp.get('venue', {}).get('fullName')
    result['broadcasts'] = (list(event['networks']) if event.get('broadcast_resolution') else
                            [name for b in comp.get('broadcasts', []) for name in b.get('names', [])])
    result['statistics'] = [{'name': c.get('team', {}).get('displayName') or c.get('athlete', {}).get('displayName'),
                             'values': [{'label': s.get('shortDisplayName') or s.get('displayName') or s.get('name'), 'value': s.get('displayValue')} for s in c.get('statistics', []) if s.get('displayValue') is not None][:12],
                             'periods': [s.get('displayValue', s.get('value')) for s in c.get('linescores', [])]}
                            for c in comp.get('competitors', [])]
    if league == 'MLB':
        for row in result['statistics']:
            row['values'] = [v for v in row['values'] if str(v['label']).lower() in ('hits','runs','errors','h','r','e')]
    result['last_play'] = situation.get('lastPlay', {}).get('text') if event['state']=='live' and not stale else None
    def person(role):
        entry = situation.get(role) if isinstance(situation.get(role), dict) else {}
        athlete = entry.get('athlete') or {}
        if not athlete.get('displayName'):
            return None
        shot = athlete.get('headshot')
        shot = shot.get('href') if isinstance(shot, dict) else shot
        jersey = str(athlete.get('jersey') or '')
        position = athlete.get('position')
        position = position.get('abbreviation') if isinstance(position, dict) else position
        line = entry.get('summary')
        return {'role': role.title(), 'name': athlete['displayName'][:80],
                'jersey': jersey if re.fullmatch(r'\d{1,3}', jersey) else None,
                'position': position[:6] if isinstance(position, str) and re.fullmatch(r'[A-Z0-9]{1,6}', position) else None,
                # Official ESPN headshot only; anything else is dropped.
                'headshot': shot if isinstance(shot, str) and re.fullmatch(r'https://a\.espncdn\.com/i/headshots/[a-z]+/players/full/\d+\.png', shot) else None,
                'today': line[:80] if isinstance(line, str) and not re.search(r'https?://', line) else None}
    result['participants'] = [p for p in (person(r) for r in ('batter', 'pitcher')) if p] if event['state']=='live' and not stale else []
    if league == 'UFC / MMA':
        result['bouts'] = [{'name': c.get('headline') or 'Bout', 'status': c.get('status', {}).get('type', {}).get('detail'),
                            'fighters': [{'name': v.get('athlete', {}).get('displayName') or v.get('athlete', {}).get('fullName'), 'winner': v.get('winner') is True} for v in c.get('competitors', [])]}
                           for c in raw.get('competitions', [])]
    if stale or event['state'] != 'live':
        return result
    def integer(key, low, high):
        value = situation.get(key)
        return value if type(value) is int and low <= value <= high else None
    if league == 'MLB':
        balls, strikes, outs = integer('balls', 0, 4), integer('strikes', 0, 3), integer('outs', 0, 3)
        bases = [situation.get(k) for k in ('onFirst', 'onSecond', 'onThird')]
        if None not in (balls, strikes, outs) and all(type(v) is bool for v in bases):
            result['graphics'] = {'kind': 'baseball', 'bases': bases, 'balls': balls, 'strikes': strikes, 'outs': outs}
    elif league in ('NFL', 'College football'):
        down, distance, yard = integer('down', 1, 4), integer('distance', 0, 100), integer('yardLine', 0, 100)
        possession = str(situation.get('possession') or '')
        ids = {str(c.get('team', {}).get('id')) for c in comp.get('competitors', [])}
        if None not in (down, distance, yard) and possession in ids and situation.get('possessionText'):
            result['graphics'] = {'kind': 'football', 'down': down, 'distance': distance, 'yard_line': yard,
                                  'possession': possession, 'spot': situation['possessionText'],
                                  'description': situation.get('downDistanceText')}
    elif league in ('NBA', 'WNBA') and type(result['period']) is int and result['period'] > 0 and isinstance(result['clock'], str):
        possession = str(situation.get('possession') or '')
        ids = {str(c.get('team', {}).get('id')) for c in comp.get('competitors', [])}
        result['graphics'] = {'kind': 'basketball', 'possession': possession if possession in ids else None,
                              'period': result['period'], 'clock': result['clock']}
    elif league == 'UFC / MMA':
        live = next((c for c in raw.get('competitions', []) if c.get('status', {}).get('type', {}).get('state') == 'in'), None)
        if live and type(live.get('status', {}).get('period')) is int and isinstance(live.get('status', {}).get('displayClock'), str):
            result['graphics'] = {'kind': 'mma', 'period': live.get('status', {}).get('period'), 'clock': live.get('status', {}).get('displayClock'),
                                  'fighters': [c.get('athlete', {}).get('displayName') or c.get('athlete', {}).get('fullName') for c in live.get('competitors', [])]}
    return result

def number(value):
    try:
        return f'{float(value):g}'
    except (ValueError, TypeError):
        return ''

def supplement(events, day):
    """Customer edition: no household supplemental schedule file."""
    return list(events)

def mlb_postseason(raw, league):
    """Use explicit MLB season metadata, never a date, matchup or channel name."""
    if league != 'MLB':
        return False
    season = raw.get('season') or {}
    if not isinstance(season, dict):
        return False
    if type(season.get('type')) is int and season['type'] == 3:
        return True
    ref = season.get('$ref')
    return isinstance(ref, str) and bool(re.fullmatch(
        r'https?://sports\.core\.api\.espn\.com/v2/sports/baseball/leagues/mlb/seasons/[0-9]{4}/types/3(?:\?[^#]*)?', ref))

def _report_health_split(base, decorated):
    """Keep schedule staleness and tracker report health in separate fields."""
    if decorated is base or not isinstance(decorated, dict):
        return decorated
    snapshot = decorated.get('game_snapshot') if isinstance(decorated.get('game_snapshot'), dict) else {}
    decorated['report_stale'] = snapshot.get('source_health', 'fresh') != 'fresh'
    decorated['stale'] = base.get('stale') is True
    return decorated
